-- Copy to Sheets, row by row (phase 6, 3 Oct 2026; generated by setup/build-mirror-sql.mjs — edit that, not this).
-- Every insert, update or delete on a table that changes while the app runs records the row's key in mirror_changes
-- (a trigger, so no code path can forget). The schedule copies just those rows to their own row of the sheet
-- (mirror_rows remembers which), instead of clearing and rewriting whole tabs. v is a random version: a change made
-- while a row is being copied replaces it, so the copy cannot lose it. This replaces mirror_state.dirty for these tables.
CREATE TABLE mirror_changes (tbl TEXT NOT NULL, k1 NOT NULL, k2 NOT NULL DEFAULT '', v INTEGER NOT NULL, PRIMARY KEY (tbl, k1, k2)) WITHOUT ROWID;
CREATE TABLE mirror_rows (tbl TEXT NOT NULL, k1 NOT NULL, k2 NOT NULL DEFAULT '', "row" INTEGER NOT NULL, PRIMARY KEY (tbl, k1, k2)) WITHOUT ROWID;
-- mode: 'build' = (re)building the tab from the table in rowid order (last_id = rowid reached, rows = rows written);
-- 'live' = copying changes. rows = the highest data row in use (a deleted row is left blank).
ALTER TABLE mirror_state ADD COLUMN mode TEXT NOT NULL DEFAULT '';
ALTER TABLE mirror_state ADD COLUMN rows INTEGER NOT NULL DEFAULT 0;
-- weekly tables (attendance): the week being copied and how far (last_id = the last week copied whole, as YYYYMMDD)
ALTER TABLE mirror_state ADD COLUMN cursor TEXT NOT NULL DEFAULT '';
-- the replay cache (a reply kept 6 hours per request id): one database write per write call instead of two (no rowid)
DROP TABLE replies;
CREATE TABLE replies (key TEXT PRIMARY KEY, body TEXT NOT NULL, at INTEGER NOT NULL) WITHOUT ROWID;
CREATE TRIGGER mirror_accounts_ins AFTER INSERT ON accounts BEGIN DELETE FROM mirror_changes WHERE tbl = 'accounts' AND k1 = NEW."login" AND k2 = ''; INSERT INTO mirror_changes (tbl, k1, k2, v) VALUES ('accounts', NEW."login", '', random() & 4503599627370495); END;
CREATE TRIGGER mirror_accounts_upd AFTER UPDATE ON accounts BEGIN DELETE FROM mirror_changes WHERE tbl = 'accounts' AND k1 = NEW."login" AND k2 = ''; INSERT INTO mirror_changes (tbl, k1, k2, v) VALUES ('accounts', NEW."login", '', random() & 4503599627370495); END;
CREATE TRIGGER mirror_accounts_key AFTER UPDATE ON accounts WHEN OLD."login" IS NOT NEW."login" BEGIN DELETE FROM mirror_changes WHERE tbl = 'accounts' AND k1 = OLD."login" AND k2 = ''; INSERT INTO mirror_changes (tbl, k1, k2, v) VALUES ('accounts', OLD."login", '', random() & 4503599627370495); END;
CREATE TRIGGER mirror_accounts_del AFTER DELETE ON accounts BEGIN DELETE FROM mirror_changes WHERE tbl = 'accounts' AND k1 = OLD."login" AND k2 = ''; INSERT INTO mirror_changes (tbl, k1, k2, v) VALUES ('accounts', OLD."login", '', random() & 4503599627370495); END;
INSERT OR IGNORE INTO mirror_state (tbl) VALUES ('accounts');
UPDATE mirror_state SET mode = 'build', last_id = 0, rows = 0, gen = 0, cursor = '' WHERE tbl = 'accounts';
